## 四、ECC 核心 Hooks 完整实现解析

### Hook 4.1：Console.log 检测（PostToolUse）

```javascript
// scripts/hooks/post-edit-console-check.js
const fs = require('fs')
const path = require('path')

const filePath = process.env.TOOL_INPUT_FILE_PATH || ''
const content = process.env.TOOL_RESULT_CONTENT || ''

// 只检查 JS/TS 文件
const jsExtensions = ['.ts', '.tsx', '.js', '.jsx', '.mts', '.mjs']
if (!jsExtensions.some(ext => filePath.endsWith(ext))) {
  process.exit(0)
}

// 检测 console.log（但允许 logger.* 和 console.error/warn）
const lines = content.split('\n')
const violations = []

lines.forEach((line, index) => {
  // 跳过注释行
  if (line.trim().startsWith('//') || line.trim().startsWith('*')) return
  // 跳过 console.error 和 console.warn（这些有合理用途）
  if (/console\.(error|warn|info)/.test(line)) return
  // 标记 console.log
  if (/console\.log/.test(line)) {
    violations.push({ line: index + 1, content: line.trim() })
  }
})

if (violations.length > 0) {
  console.error('\n🚨 [Hook] console.log 检测到，请在提交前移除：\n')
  violations.forEach(({ line, content }) => {
    console.error(`  Line ${line}: ${content}`)
  })
  console.error('\n💡 替代方案：')
  console.error('  - 调试日志：使用 logger.debug()')
  console.error('  - 生产日志：使用 logger.info() / logger.error()')
  console.error('  - 临时调试完成后立即删除\n')
}

// 不阻断（exit 0），只是警告
process.exit(0)
```

