  // AWS
  { pattern: /AKIA[0-9A-Z]{16}/, name: 'AWS Access Key ID' },
  { pattern: /[0-9a-zA-Z/+]{40}(?=[^0-9a-zA-Z/+]|$)/, name: 'AWS Secret (context-sensitive)' },

  // GCP / Firebase
  { pattern: /AIza[0-9A-Za-z-_]{35}/, name: 'Google API Key' },

