### Hook 4.5：TypeScript 类型检查（PostToolUse）

```javascript
// scripts/hooks/post-edit-typecheck.js
const { execSync } = require('child_process')
const { TOOL_INPUT_FILE_PATH: filePath } = process.env

// 只对 TypeScript 文件触发
if (!filePath?.match(/\.(ts|tsx|mts)$/)) {
  process.exit(0)
}

// 检查是否有 tsconfig.json
const fs = require('fs')
const path = require('path')

let projectRoot = path.dirname(filePath)
let foundTsConfig = false

// 向上查找 tsconfig.json
while (projectRoot !== path.dirname(projectRoot)) {
  if (fs.existsSync(path.join(projectRoot, 'tsconfig.json'))) {
    foundTsConfig = true
    break
  }
  projectRoot = path.dirname(projectRoot)
}

if (!foundTsConfig) {
  process.exit(0)  // 没有 tsconfig，跳过检查
}

try {
  execSync('npx tsc --noEmit --skipLibCheck', {
    cwd: projectRoot,
    stdio: 'pipe',
    timeout: 30000  // 30秒超时
  })
  console.log('✅ TypeScript: 类型检查通过')
} catch (error) {
  const stderr = error.stderr?.toString() || ''
  const errorLines = stderr.split('\n').filter(line => line.includes('error TS'))

  if (errorLines.length > 0) {
    console.error('\n🔴 [TypeCheck] TypeScript 类型错误：\n')
    // 只显示前 10 个错误，避免刷屏
    errorLines.slice(0, 10).forEach(line => {
      console.error('  ' + line)
    })
    if (errorLines.length > 10) {
      console.error(`  ... 还有 ${errorLines.length - 10} 个错误\n`)
    }
  }
  // 不阻断（exit 0），错误信息已输出，AI 会看到并主动修复
}

process.exit(0)
```

