## 五、内存持久化 Hook 系统（跨会话记忆）

这是 ECC Hooks 中最复杂、最有价值的功能——让 AI 在不同会话间保持"记忆"。

### SessionStart Hook：加载上次会话记忆

```javascript
// scripts/hooks/session-start.js
const fs = require('fs')
const path = require('path')

const MEMORY_DIR = path.join(process.env.HOME, '.claude', 'memory')
const LATEST_SUMMARY = path.join(MEMORY_DIR, 'session-latest.json')

// 确保目录存在
if (!fs.existsSync(MEMORY_DIR)) {
  fs.mkdirSync(MEMORY_DIR, { recursive: true })
  process.exit(0)  // 第一次使用，没有历史
}

if (!fs.existsSync(LATEST_SUMMARY)) {
  process.exit(0)  // 没有上次会话记录
}

try {
  const memory = JSON.parse(fs.readFileSync(LATEST_SUMMARY, 'utf8'))

  // 检查是否太旧（超过 7 天的记忆可能已经过时）
  const daysSince = (Date.now() - new Date(memory.timestamp).getTime()) / (1000 * 60 * 60 * 24)
  if (daysSince > 7) {
    console.log(`[Memory] 上次会话超过 7 天前，跳过加载旧记忆`)
    process.exit(0)
  }

  // 将记忆注入到会话开始的上下文
  const contextBlock = `
╔══════════════════════════════════════════════════════════╗
║                  📚 上次会话记忆                          ║
║  时间：${memory.timestamp}
╠══════════════════════════════════════════════════════════╣
║ 项目状态：
${memory.project_state?.split('\n').map(l => '║   ' + l).join('\n') || '║   （无记录）'}
╠══════════════════════════════════════════════════════════╣
║ 进行中的任务：
${memory.in_progress_tasks?.map(t => `║   • ${t}`).join('\n') || '║   （无）'}
╠══════════════════════════════════════════════════════════╣
║ 关键技术决策：
${memory.key_decisions?.map(d => `║   • ${d}`).join('\n') || '║   （无）'}
╠══════════════════════════════════════════════════════════╣
║ 建议的下一步：
${memory.next_steps?.split('\n').map(l => '║   ' + l).join('\n') || '║   （无）'}
╚══════════════════════════════════════════════════════════╝
`

  // 通过 stdout 注入上下文（Claude Code 会读取这个输出）
  process.stdout.write(contextBlock)

} catch (err) {
  console.error('[Memory] 加载记忆失败：', err.message)
}

process.exit(0)
```

### Stop Hook：保存会话记忆

```javascript
// scripts/hooks/session-end.js
const fs = require('fs')
const path = require('path')
const Anthropic = require('@anthropic-ai/sdk')

const MEMORY_DIR = path.join(process.env.HOME, '.claude', 'memory')
const LATEST_SUMMARY = path.join(MEMORY_DIR, 'session-latest.json')

async function summarizeAndSave() {
  // 获取当前会话的历史（通过 Claude Code 的会话 API）
  const sessionHistory = process.env.CLAUDE_SESSION_HISTORY || ''

  if (!sessionHistory || sessionHistory.length < 500) {
    // 会话太短，没有值得记录的内容
    return
  }

  const client = new Anthropic()

  try {
    const response = await client.messages.create({
      model: 'claude-haiku-20241022',  // 用便宜的模型做摘要
      max_tokens: 1000,
      messages: [{
        role: 'user',
        content: `请分析以下 AI 编程会话，提取关键信息用于下次会话的上下文继承。

输出 JSON 格式（严格遵守，不要有其他内容）：
{
  "project_state": "项目当前状态的简要描述（2-3句话）",
  "in_progress_tasks": ["正在进行的任务列表"],
  "key_decisions": ["本次会话中做出的重要技术决策"],
  "next_steps": "下次会话建议的起始点",
  "files_modified": ["被修改的关键文件路径"],
  "open_issues": ["发现但未解决的问题"]
}

会话历史摘要：
${sessionHistory.slice(-10000)}  // 只取最后 10000 字符
`
      }]
    })

    const summaryText = response.content[0].text
    const summary = JSON.parse(summaryText)

    // 添加时间戳
    summary.timestamp = new Date().toISOString()

    // 保存到文件
    fs.mkdirSync(MEMORY_DIR, { recursive: true })
    fs.writeFileSync(LATEST_SUMMARY, JSON.stringify(summary, null, 2))

    // 同时保存带时间戳的历史版本（保留最近 10 次）
    const historyFile = path.join(MEMORY_DIR, `session-${Date.now()}.json`)
    fs.writeFileSync(historyFile, JSON.stringify(summary, null, 2))

    // 清理超过 10 个的历史文件
    const historyFiles = fs.readdirSync(MEMORY_DIR)
      .filter(f => f.startsWith('session-') && f !== 'session-latest.json')
      .sort()
      .reverse()

    historyFiles.slice(10).forEach(f => {
      fs.unlinkSync(path.join(MEMORY_DIR, f))
    })

    console.log('✅ [Memory] 会话记忆已保存')

  } catch (err) {
    console.error('[Memory] 保存记忆失败：', err.message)
  }
}

summarizeAndSave().catch(console.error)
```

