## 八、DRY 适配器模式实现

ECC 用适配器模式解决了 Cursor 和 Claude Code Hook 格式不同的问题：

```javascript
// .cursor/hooks/adapter.js
// 这是所有 Cursor Hook 的统一入口点

const path = require('path')
const { execFileSync } = require('child_process')

// Cursor 的事件到 Claude Code 事件格式的映射
const EVENT_MAP = {
  'beforeShellExecution': 'PreToolUse:Bash',
  'afterFileEdit': 'PostToolUse:Edit',
  'sessionStart': 'SessionStart',
  'beforeSubmitPrompt': 'PreSubmit',
  'beforeTabFileRead': 'PreRead:Tab',
  'beforeMCPExecution': 'PreToolUse:MCP',
  'afterMCPExecution': 'PostToolUse:MCP',
}

// Cursor stdin 格式转换为 Claude Code 环境变量格式
function transformInput(cursorEvent, cursorInput) {
  const claudeEvent = EVENT_MAP[cursorEvent] || cursorEvent
  const env = { ...process.env }

  switch (cursorEvent) {
    case 'beforeShellExecution':
      env.TOOL_INPUT_COMMAND = cursorInput.command || ''
      env.CLAUDE_HOOK_EVENT = 'PreToolUse'
      break

    case 'afterFileEdit':
      env.TOOL_INPUT_FILE_PATH = cursorInput.filePath || ''
      env.TOOL_RESULT_CONTENT = cursorInput.newContent || ''
      env.CLAUDE_HOOK_EVENT = 'PostToolUse'
      break

    case 'beforeSubmitPrompt':
      env.CURSOR_PROMPT = cursorInput.prompt || ''
      env.CLAUDE_HOOK_EVENT = 'PreSubmit'
      break

    default:
      env.CLAUDE_HOOK_EVENT = cursorEvent
  }

  return env
}

// 主逻辑：读取 Cursor stdin，转换，调用共享脚本
async function main() {
  const event = process.env.CURSOR_HOOK_EVENT
  const input = JSON.parse(process.env.CURSOR_HOOK_INPUT || '{}')

  const env = transformInput(event, input)

  // 选择要运行的共享脚本
  const SCRIPT_MAP = {
    'beforeShellExecution': [
      'scripts/hooks/pre-bash-secret-check.js',
      'scripts/hooks/pre-bash-tmux-check.js',
      'scripts/hooks/pre-bash-git-push-check.js',
    ],
    'afterFileEdit': [
      'scripts/hooks/post-edit-console-check.js',
      'scripts/hooks/post-edit-typecheck.js',
    ],
    'beforeSubmitPrompt': [
      'scripts/hooks/pre-submit-secret-check.js',
    ],
  }

  const scripts = SCRIPT_MAP[event] || []

  for (const script of scripts) {
    const scriptPath = path.join(__dirname, '../../', script)
    try {
      execFileSync('node', [scriptPath], { env, stdio: 'inherit' })
    } catch (err) {
      if (err.status === 2) {
        // 阻断
        process.exit(2)
      }
      // 其他错误不阻断，只记录
      console.error(`Hook ${script} error:`, err.message)
    }
  }
}

main().catch(console.error)
```

