## 九、OpenCode Hook 系统

OpenCode 通过插件系统支持 11 种 Hook 事件：

```javascript
// .opencode/plugin.js（OpenCode 插件格式）
module.exports = {
  name: 'ecc-hooks',
  version: '1.9.0',

  hooks: {
    // 对应 Claude Code PreToolUse
    'tool.execute.before': async ({ tool, input, context }) => {
      if (tool === 'bash') {
        const result = await runScript('pre-bash-secret-check', { command: input.command })
        if (result.exitCode === 2) {
          return { block: true, message: result.output }
        }
      }
    },

    // 对应 Claude Code PostToolUse
    'tool.execute.after': async ({ tool, input, output, context }) => {
      if (tool === 'file_write' && isJSFile(input.path)) {
        await runScript('post-edit-console-check', {
          filePath: input.path,
          content: output.content
        })
      }
    },

    // 对应 Claude Code SessionStart
    'session.created': async ({ session }) => {
      await runScript('session-start', { sessionId: session.id })
    },

    // OpenCode 独有：文件系统监控
    'file.watcher.updated': async ({ path, changeType }) => {
      if (changeType === 'modified' && isConfigFile(path)) {
        console.warn(`⚠️  配置文件变更：${path}`)
      }
    },

    // OpenCode 独有：LSP 诊断集成
    'lsp.client.diagnostics': async ({ diagnostics, uri }) => {
      const errors = diagnostics.filter(d => d.severity === 'error')
      if (errors.length > 0) {
        console.error(`🔴 LSP 错误 in ${uri}：${errors.length} 个错误`)
      }
    },
  }
}
```

