## 十、Hook 的测试与调试

ECC 对所有 Hook 脚本都有单元测试（997 个测试之一）：

```javascript
// tests/hooks/pre-bash-secret-check.test.js
const { execSync } = require('child_process')
const path = require('path')

function runHook(command) {
  try {
    execSync(`node ${path.join(__dirname, '../../scripts/hooks/pre-bash-secret-check.js')}`, {
      env: {
        ...process.env,
        TOOL_INPUT_COMMAND: command
      },
      stdio: 'pipe'
    })
    return { exitCode: 0, blocked: false }
  } catch (err) {
    return {
      exitCode: err.status,
      blocked: err.status === 2,
      output: err.stderr?.toString()
    }
  }
}

describe('pre-bash-secret-check', () => {
  test('should block commands containing Anthropic API key', () => {
    const result = runHook('curl -H "Authorization: Bearer sk-ant-api03-xxxxxxxxxxx" https://api.anthropic.com')
    expect(result.blocked).toBe(true)
    expect(result.output).toContain('Anthropic Claude API Key')
  })

  test('should block commands containing GitHub token', () => {
    const result = runHook('gh auth login --with-token <<< ghp_abc123def456ghi789jkl012mno345pqr')
    expect(result.blocked).toBe(true)
  })

  test('should allow safe commands', () => {
    const result = runHook('git status')
    expect(result.blocked).toBe(false)
  })

  test('should allow environment variable references', () => {
    const result = runHook('curl -H "Authorization: Bearer $ANTHROPIC_API_KEY" https://api.anthropic.com')
    expect(result.blocked).toBe(false)
  })
})
```

