## 十二、构建自定义 Hook

以下是构建项目专属 Hook 的完整指南：

### 示例：Prisma Schema 安全检查

```javascript
// hooks/custom/pre-edit-prisma-safety.js
// 检查 Prisma schema 变更是否安全

const fs = require('fs')
const filePath = process.env.TOOL_INPUT_FILE_PATH || ''

if (!filePath.endsWith('schema.prisma')) {
  process.exit(0)
}

// 读取原始文件（变更前）
let originalContent = ''
try {
  originalContent = fs.readFileSync(filePath, 'utf8')
} catch (e) {
  process.exit(0)  // 文件不存在（新建），安全
}

// 获取新内容（通过 stdin 或环境变量）
const newContent = process.env.TOOL_INPUT_NEW_CONTENT || ''

// 危险操作检测：字段删除
function detectDeletedFields(original, updated) {
  const originalFields = extractFields(original)
  const updatedFields = extractFields(updated)
  return originalFields.filter(f => !updatedFields.includes(f))
}

const deletedFields = detectDeletedFields(originalContent, newContent)

if (deletedFields.length > 0) {
  console.error('\n🚨 [Prisma Guard] 检测到字段删除！\n')
  console.error('被删除的字段：')
  deletedFields.forEach(f => console.error('  - ' + f))
  console.error('\n这可能导致：')
  console.error('  1. 数据丢失（如果不先迁移数据）')
  console.error('  2. 现有代码引用这些字段时报错')
  console.error('\n建议：')
  console.error('  1. 先创建数据迁移脚本')
  console.error('  2. 确认生产数据已备份')
  console.error('  3. 在测试环境验证迁移\n')

  // 阻断（这是高风险操作）
  process.exit(2)
}

process.exit(0)
```

