## 四、核心 Hooks 完整实现

### scripts/lib/utils.js（共享工具库）

```javascript
// scripts/lib/utils.js
// 被所有 Hook 脚本 require() 的共享工具库

const fs = require('fs')
const path = require('path')
const crypto = require('crypto')

/**
 * 获取 ECC 配置目录（~/.claude 或项目 .claude）
 */
function getEccDir() {
  const projectDir = process.env.PROJECT_DIR || process.cwd()
  const localDir = path.join(projectDir, '.claude')
  if (fs.existsSync(localDir)) return localDir
  return path.join(process.env.HOME, '.claude')
}

/**
 * 检查当前 Hook 是否应该运行（基于 profile 和 disabled 列表）
 */
function shouldRun(hookId) {
  const profile = process.env.ECC_HOOK_PROFILE || 'standard'
  const disabled = (process.env.ECC_DISABLED_HOOKS || '').split(',').filter(Boolean)

  // 检查是否被明确禁用
  if (disabled.includes(hookId)) return false

  // 基于 profile 过滤
  const hookProfiles = loadHookProfiles()
  const hookProfile = hookProfiles[hookId] || 'standard'

  const profileOrder = ['minimal', 'standard', 'strict']
  const currentLevel = profileOrder.indexOf(profile)
  const hookLevel = profileOrder.indexOf(hookProfile)

  return hookLevel <= currentLevel
}

/**
 * 安全地记录日志（不干扰 Hook 输出）
 */
function log(level, message) {
  const timestamp = new Date().toISOString()
  const logLine = `[${timestamp}] [ECC Hook] [${level}] ${message}\n`

  // 写到 ~/.claude/hooks.log 而非 stdout（避免污染 Hook 输出）
  const logFile = path.join(getEccDir(), 'hooks.log')
  fs.appendFileSync(logFile, logLine)

  // ERROR 级别同时输出到 stderr（AI 可以看到）
  if (level === 'ERROR') process.stderr.write(message + '\n')
}

module.exports = { getEccDir, shouldRun, log }
```

