### Hook 1：console.log 警告（PostToolUse）

```javascript
// scripts/hooks/post-edit-console-check.js
'use strict'

const { shouldRun, log } = require('../lib/utils')

const HOOK_ID = 'post:edit:console-check'

if (!shouldRun(HOOK_ID)) {
  process.exit(0)
}

const filePath = process.env.FILE_PATH || ''
const newContent = process.env.NEW_CONTENT || ''

// 只检查 JS/TS/JSX/TSX 文件
const jsPattern = /\.(ts|tsx|js|jsx|mjs|cjs)$/
if (!jsPattern.test(filePath)) {
  process.exit(0)
}

// 检测 console.log（排除注释和 // eslint-disable 行）
const lines = newContent.split('\n')
const consoleLogs = lines
  .map((line, idx) => ({ lineNum: idx + 1, text: line }))
  .filter(({ text }) => {
    const trimmed = text.trim()
    // 跳过注释行
    if (trimmed.startsWith('//') || trimmed.startsWith('*')) return false
    // 跳过已禁用的行
    if (trimmed.includes('// eslint-disable')) return false
    return /console\.(log|debug|info|warn|dir|table)\(/.test(trimmed)
  })

if (consoleLogs.length > 0) {
  const fileShort = filePath.split('/').slice(-2).join('/')

  process.stderr.write(`\n⚠️  [ECC Hook] console.log detected in ${fileShort}:\n`)
  consoleLogs.forEach(({ lineNum, text }) => {
    process.stderr.write(`   Line ${lineNum}: ${text.trim()}\n`)
  })
  process.stderr.write(`
   → Use structured logging instead:
     logger.debug({ context }, 'message')
   → Or remove before committing
   → This is a WARNING, not a blocker. But CI will fail on console.log.\n\n`)
}

log('INFO', `console-check: ${consoleLogs.length} issues in ${filePath}`)
process.exit(0)  // 警告但不阻断
```

