const { shouldRun, log } = require('../lib/utils')

const HOOK_ID = 'pre:bash:devserver-check'

if (!shouldRun(HOOK_ID)) {
  process.exit(0)
}

const command = process.env.COMMAND || ''

// 长时间运行的前台进程模式
const BLOCKING_PATTERNS = [
  /\b(npm|pnpm|yarn|bun)\s+run\s+dev\b/,
  /\b(npm|pnpm|yarn|bun)\s+run\s+start\b/,
  /python\s+manage\.py\s+runserver/,
  /flask\s+run\b/,
  /fastapi\s+dev\b/,
  /uvicorn\s+main:app/,
  /go\s+run\s+\.\s*$/,
  /cargo\s+run\b/,
  /rails\s+server\b/,
]

const isBlocking = BLOCKING_PATTERNS.some(p => p.test(command))
if (!isBlocking) {
  process.exit(0)
}

// 检查是否在 tmux session 中
const inTmux = !!(process.env.TMUX || process.env.TERM_PROGRAM === 'tmux')

if (!inTmux) {
  process.stderr.write(`
🚫 [ECC Hook] BLOCKED: Long-running server must run in tmux!

Command: ${command}

This server process will block Claude's Bash tool if run in foreground,
making Claude unable to execute any further Bash commands.

How to fix:
  Option A (recommended):
    tmux new-session -d -s dev '${command}'
    tmux attach -t dev

  Option B (background):
    ${command} &
    # Note: background processes may not survive session end

  Option C:
    Set ECC_DISABLED_HOOKS=pre:bash:devserver-check to bypass
    (not recommended for normal use)
`)

  log('WARN', `Blocked: dev server started outside tmux: ${command}`)
  process.exit(2)
}

log('INFO', `dev server: running inside tmux, allowed: ${command}`)
process.exit(0)
