### Hook 4：TypeScript 类型检查（PostToolUse）

```javascript
// scripts/hooks/post-edit-typecheck.js
'use strict'

const { execSync } = require('child_process')
const path = require('path')
const { shouldRun, log } = require('../lib/utils')

const HOOK_ID = 'post:edit:typecheck'

if (!shouldRun(HOOK_ID)) {
  process.exit(0)
}

const filePath = process.env.FILE_PATH || ''
const projectDir = process.env.PROJECT_DIR || process.cwd()

// 只对 TypeScript 文件触发
if (!/\.(ts|tsx)$/.test(filePath)) {
  process.exit(0)
}

// 检查是否有 tsconfig.json（避免在非 TS 项目运行）
const tsconfigPath = path.join(projectDir, 'tsconfig.json')
const fs = require('fs')
if (!fs.existsSync(tsconfigPath)) {
  log('INFO', 'typecheck: no tsconfig.json found, skipping')
  process.exit(0)
}

// 运行 TypeScript 类型检查（增量模式，只检查变更）
try {
  execSync('npx tsc --noEmit --incremental', {
    cwd: projectDir,
    stdio: 'pipe',
    timeout: 30000  // 30 秒超时
  })

  log('INFO', `typecheck: passed for ${filePath}`)
  process.exit(0)

} catch (error) {
  const stdout = error.stdout?.toString() || ''
  const stderr = error.stderr?.toString() || ''
  const output = stdout || stderr

  // 格式化输出，让 AI 容易理解
  const errors = output
    .split('\n')
    .filter(line => line.includes('error TS'))
    .slice(0, 10)  // 最多显示 10 个错误

  if (errors.length > 0) {
    process.stderr.write(`\n🔴 [TypeCheck] Type errors detected after editing ${filePath.split('/').pop()}:\n\n`)
    errors.forEach(err => process.stderr.write(`  ${err}\n`))
    if (errors.length === 10) {
      process.stderr.write(`  ... and more (run tsc --noEmit for full output)\n`)
    }
    process.stderr.write('\n  Fix these type errors before proceeding.\n\n')
  }

  log('ERROR', `typecheck: failed for ${filePath}: ${errors.length} errors`)
  process.exit(0)  // 不阻断（AI 可以看到错误并修复），但不用 exit(2)
}
```

