## 五、内存持久化

这是 ECC 最复杂、最有价值的 Hook 对，实现跨会话的"记忆"功能。

### session-start.js（SessionStart Hook）

```javascript
// scripts/hooks/session-start.js
'use strict'

const fs = require('fs')
const path = require('path')
const { getEccDir, shouldRun, log } = require('../lib/utils')

const HOOK_ID = 'session:start:memory'

if (!shouldRun(HOOK_ID)) {
  process.exit(0)
}

const eccDir = getEccDir()
const memoryDir = path.join(eccDir, 'memory')
const latestFile = path.join(memoryDir, 'session-latest.json')

if (!fs.existsSync(latestFile)) {
  log('INFO', 'session-start: no previous session memory found')
  process.exit(0)
}

try {
  const memory = JSON.parse(fs.readFileSync(latestFile, 'utf8'))

  // 检查记忆是否太旧（超过 7 天的记忆可能不再相关）
  const savedAt = new Date(memory.saved_at)
  const ageHours = (Date.now() - savedAt.getTime()) / (1000 * 60 * 60)

  if (ageHours > 168) {  // 7 天
    log('INFO', `session-start: memory is ${Math.floor(ageHours/24)} days old, injecting with caution`)
  }

  // 构建上下文注入（写到 stdout，Claude Code 会注入到系统提示）
  const contextBlock = [
    '╔══════════════════════════════════════╗',
    '║      Previous Session Memory         ║',
    `╠══════════════════════════════════════╣`,
    `║ Saved: ${memory.saved_at.substring(0, 16).padEnd(32)} ║`,
    '╚══════════════════════════════════════╝',
    '',
    `**Project State**: ${memory.project_state || 'Not recorded'}`,
    '',
    '**In-Progress Tasks**:',
    ...(memory.in_progress_tasks || []).map(t => `  - ${t}`),
    '',
    '**Key Technical Decisions**:',
    ...(memory.key_decisions || []).map(d => `  - ${d}`),
    '',
    `**Next Steps**: ${memory.next_steps || 'Not recorded'}`,
    '',
    '**Technology Context**:',
    `  Languages: ${(memory.tech_stack?.languages || []).join(', ')}`,
    `  Frameworks: ${(memory.tech_stack?.frameworks || []).join(', ')}`,
    `  Key Libraries: ${(memory.tech_stack?.key_libraries || []).join(', ')}`,
    '',
    '════════════════════════════════════════',
    '(End of session memory — verify before trusting)',
    '',
  ].join('\n')

  // 写到 stdout → Claude Code 注入到会话上下文
  process.stdout.write(contextBlock)

  log('INFO', `session-start: injected ${contextBlock.length} chars of memory`)
  process.exit(0)

} catch (error) {
  log('ERROR', `session-start: failed to load memory: ${error.message}`)
  process.exit(0)  // 失败时静默跳过，不影响正常会话
}
```

### session-end.js（Stop Hook）

```javascript
// scripts/hooks/session-end.js
'use strict'

const fs = require('fs')
const path = require('path')
const { getEccDir, shouldRun, log } = require('../lib/utils')

// 使用 Claude API 生成会话摘要
async function summarizeSession() {
  const HOOK_ID = 'session:stop:save'

  if (!shouldRun(HOOK_ID)) {
    return
  }

  const eccDir = getEccDir()
  const memoryDir = path.join(eccDir, 'memory')

  if (!fs.existsSync(memoryDir)) {
    fs.mkdirSync(memoryDir, { recursive: true })
  }

  // 获取当前会话历史（Claude Code 提供）
  const sessionHistory = process.env.SESSION_HISTORY || ''

  if (!sessionHistory || sessionHistory.length < 100) {
    log('INFO', 'session-end: session too short to summarize')
    return
  }

  // 调用 Claude API 生成结构化摘要
  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',  // 用最便宜的模型做摘要
        max_tokens: 1000,
        messages: [{
          role: 'user',
          content: `Analyze this Claude Code session and extract a structured summary.

Session history (last 10k chars):
${sessionHistory.slice(-10000)}

Return JSON only, no markdown:
{
  "project_state": "one sentence describing current project state",
  "in_progress_tasks": ["task 1", "task 2"],
  "key_decisions": ["decision 1: rationale", "decision 2: rationale"],
  "next_steps": "what should happen next",
  "tech_stack": {
    "languages": ["TypeScript"],
    "frameworks": ["Next.js"],
    "key_libraries": ["Supabase", "Zod"]
  },
  "blockers": ["any known blockers or issues"]
}`
        }]
      })
    })

    const data = await response.json()
    const summaryText = data.content?.[0]?.text || '{}'

    // 清理 JSON（移除可能的 markdown 代码块）
    const cleanJson = summaryText
      .replace(/```json\n?/g, '')
      .replace(/```\n?/g, '')
      .trim()

    const summary = JSON.parse(cleanJson)
    summary.saved_at = new Date().toISOString()
    summary.session_id = process.env.SESSION_ID

    // 保存最新摘要
    const latestFile = path.join(memoryDir, 'session-latest.json')
    fs.writeFileSync(latestFile, JSON.stringify(summary, null, 2))

    // 保存历史存档（按日期）
    const dateStr = new Date().toISOString().split('T')[0]
    const archiveFile = path.join(memoryDir, `session-${dateStr}.json`)
    fs.writeFileSync(archiveFile, JSON.stringify(summary, null, 2))

    log('INFO', `session-end: saved memory to ${latestFile}`)

  } catch (error) {
    log('ERROR', `session-end: failed to summarize session: ${error.message}`)
    // 失败时静默跳过，不影响正常关闭
  }
}

summarizeSession().catch(e => {
  log('ERROR', `session-end: unexpected error: ${e.message}`)
})
```

