## 六、战略压缩 Hooks

### pre-compact.js（PreCompact Hook）

```javascript
// scripts/hooks/pre-compact.js
'use strict'

const fs = require('fs')
const path = require('path')
const { getEccDir, log } = require('../lib/utils')

// 在压缩前保存当前状态快照（防止压缩后丢失关键上下文）
function savePreCompactState() {
  const eccDir = getEccDir()
  const checkpointDir = path.join(eccDir, 'checkpoints')

  if (!fs.existsSync(checkpointDir)) {
    fs.mkdirSync(checkpointDir, { recursive: true })
  }

  const checkpoint = {
    timestamp: new Date().toISOString(),
    trigger: 'pre-compact',
    context_usage_pct: parseInt(process.env.CONTEXT_USAGE_PCT || '0'),
    session_id: process.env.SESSION_ID,
    // 保存关键状态（由 Claude Code 注入）
    active_files: (process.env.ACTIVE_FILES || '').split(',').filter(Boolean),
    pending_todos: (process.env.PENDING_TODOS || '').split('\n').filter(Boolean),
  }

  const checkpointFile = path.join(
    checkpointDir,
    `checkpoint-${Date.now()}.json`
  )

  fs.writeFileSync(checkpointFile, JSON.stringify(checkpoint, null, 2))
  log('INFO', `pre-compact: saved checkpoint to ${checkpointFile}`)
}

savePreCompactState()
process.exit(0)
```

### suggest-compact.js（Stop Hook，战略压缩建议）

```javascript
// scripts/hooks/suggest-compact.js
'use strict'

const { log } = require('../lib/utils')

// 分析当前会话状态，决定是否建议压缩
function analyzeCompactTiming() {
  const contextUsagePct = parseInt(process.env.CONTEXT_USAGE_PCT || '0')
  const pendingTodos = (process.env.PENDING_TODOS || '')
    .split('\n')
    .filter(t => t.trim().startsWith('[ ]'))  // 未完成的 TODO

  const activeTasks = (process.env.ACTIVE_TASKS || '')
    .split('\n')
    .filter(Boolean)

  // 判断是否处于实现中途（不安全的压缩时机）
  const isImplementing = activeTasks.some(task => 
    task.toLowerCase().includes('implement') || 
    task.toLowerCase().includes('writing') ||
    task.toLowerCase().includes('editing')
  )

  const hasPendingTodos = pendingTodos.length > 0

  if (contextUsagePct < 50) {
    // 上下文使用不到一半，不需要考虑压缩
    return
  }

  if (isImplementing) {
    process.stderr.write(`
⚠️  [Strategic Compact] WARNING: Unsafe to compact now!

Context usage: ${contextUsagePct}%
Reason: Implementation is in progress

Compacting mid-implementation risks losing:
  - Variable names and type definitions
  - File paths and import relationships
  - Partial implementation state

RECOMMENDED ACTION:
  1. Complete the current function/module
  2. Run: /checkpoint  (saves current state)
  3. Then run: /compact

Safe compact timing:
  ✅ After completing a milestone
  ✅ After finishing research/exploration
  ✅ Before starting a new unrelated task
`)
  } else if (hasPendingTodos && contextUsagePct > 70) {
    process.stderr.write(`
💡 [Strategic Compact] Context at ${contextUsagePct}%, ${pendingTodos.length} todos pending.

Consider: /compact to free up context for remaining tasks.
The current state is at a safe stopping point.

Run /checkpoint first to save current state snapshot.
`)
  }
}

analyzeCompactTiming()
process.exit(0)
```

